import re

from moler.exceptions import ParsingDone, CommandFailure
from ta_moler.cmd.rtg.ws.genericrtgws import GenericRtgWs

__author__ = 'Dawid Gwizdz, Marek Zajac'
__copyright__ = 'Copyright (C) 2019-2020, Nokia'
__email__ = 'dawid.gwizdz@nokia.com, marek.zajac@nokia.com'


class RtgPcapStart(GenericRtgWs):
    """Command for starting rtg-pcap script."""

    def __init__(self, connection, ctrls, path="/opt/rtg/bin/rtg-pcap", options=None, prompt=None, newline_chars=None,
                 runner=None):
        """
        Rtg pcap start command. Has to be run as root. Script has to be stopped using pcap stop command.

        :param connection: moler connection to device, terminal when command is executed.
        :param ctrls: List with controllers' numbers.
        :param path: Path to rtg-pcap script.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(RtgPcapStart, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.path = path
        self.options = options
        self.ctrls = ctrls
        self.started = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = self.path
        cmd = f"{cmd} -c {','.join(map(str, self.ctrls))}"
        if self.options:
            cmd = f"{cmd} {self.options}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_ctrl_not_found(line)
            except ParsingDone:
                pass
        else:
            try:
                self._parse_start_capturing(line)
            except ParsingDone:
                pass
        return super(RtgPcapStart, self).on_new_line(line, is_full_line)

    # Example line: Error: Controllers not given
    _re_error = re.compile(r'Error:\s*(?P<ERROR>.*)')

    def _parse_error(self, line):
        """
        Parse line containing error.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.search(self._re_error, line).group('ERROR')))
            raise ParsingDone

    # Example line: Ctrl 2 not found in INI
    _re_ctrl_not_found = re.compile(r'Ctrl (?P<CTRL_NAME>.*) not found in INI')

    def _parse_ctrl_not_found(self, line):
        """
        Parse line containing not found error.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_ctrl_not_found, line):
            self.set_exception(
                CommandFailure(self, f"Not found ctrl: {self._regex_helper.search(self._re_ctrl_not_found, line).group('CTRL_NAME')}"))
            raise ParsingDone

    # Example line: Press ENTER to start wireshark collection
    _re_start_capturing = re.compile(r'Press ENTER to start wireshark collection')

    def _parse_start_capturing(self, line):
        """
        Parse line containing capturing info.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_start_capturing, line):
            if not self.started:
                self.started = True
                self.connection.sendline('')
                self.set_result({})
            raise ParsingDone


